-- BozorPulse extended demo seed.
-- 4 customers + 10 suppliers, 120 products, 4 months of labeled demo price samples.
-- Login = password: customer1..customer4, supplier1..supplier10 (all confirmed).

ON CONFLICT (id) DO UPDATE SET password_hash=EXCLUDED.password_hash, status='confirmed', company_name=EXCLUDED.company_name, inn=EXCLUDED.inn, bank_account=EXCLUDED.bank_account, region_id=EXCLUDED.region_id, phone=EXCLUDED.phone;

ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, inn=EXCLUDED.inn, bank_account=EXCLUDED.bank_account, region_id=EXCLUDED.region_id;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

SELECT 'wh-demo-sup' || ((substring(p.id from 10)::int - 1) / 12 + 1), p.id, p.stock, '2026-11-01T00:00:00Z'
FROM products p WHERE p.id LIKE 'prd-demo-%'
ON CONFLICT (warehouse_id,product_id) DO NOTHING;

-- Four months of demo price observations, clearly labeled is_demo = true.
SELECT 'ps-demo-' || p.id || '-' || m, p.id, p.supplier_id, p.region_id,
       round((p.price * (1 + 0.012 * m))::numeric, 2), 'demo', true,
       to_char(date '2026-08-01' + m * interval '1 month', 'YYYY-MM') || '-01T00:00:00Z'
FROM products p CROSS JOIN generate_series(0,3) AS m
WHERE p.id LIKE 'prd-demo-%'
ON CONFLICT (id) DO NOTHING;

